// Monta a mensagem do WhatsApp
const meetingId = $('3. Prepare Metadata').first().json.meeting_id;
const summary = $('Aggregate').first().json.summary;
const items = $('Aggregate').all().map(i => i.json).filter(j => !j.no_actions);

const minhas = items.filter(i => i.owner === 'vitor');
const delegadas = items.filter(i => i.owner !== 'vitor');
const formatPrazo = (p) => {
  if (!p) return '';
  try {
    const d = new Date(p);
    return ' _(até ' + d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }) + ')_';
  } catch { return ''; }
};
const emojiPrio = { urgente: '🔴', alta: '🟠', media: '🟡', baixa: '⚪' };

let msg = '🎙️ *Reunião processada*\n\n';
msg += '_' + summary + '_\n\n';

if (minhas.length) {
  msg += '✅ *Minhas ações* (' + minhas.length + ')\n';
  minhas.forEach(t => {
    msg += (emojiPrio[t.prioridade] || '🟡') + ' ' + t.titulo + formatPrazo(t.prazo) + '\n';
  });
  msg += '\n';
}

if (delegadas.length) {
  msg += '👥 *Combinei com outros* (' + delegadas.length + ')\n';
  delegadas.forEach(t => {
    msg += (emojiPrio[t.prioridade] || '🟡') + ' *' + t.owner + ':* ' + t.titulo + formatPrazo(t.prazo) + '\n';
  });
  msg += '\n';
}

if (!minhas.length && !delegadas.length) {
  msg += '_(nenhuma ação concreta extraída desta reunião)_\n';
}

const frontendUrl = 'https://acoes.vitorgambetti.com.br';
msg += '🔗 ' + frontendUrl + '/reunioes/' + meetingId;


return [{ json: { text: msg, meeting_id: meetingId, n_tarefas: items.length } }];

// Monta texto rotulado a partir dos segments + speaker_labels.
// Input: meeting row do SELECT (com segments e speaker_labels).
const row = $('SELECT meeting').first().json;
const segments = row.segments || [];
const labels = row.speaker_labels || {};

if (!segments.length) {
  // sem segments — usa transcrição crua como fallback
  return [{
    json: {
      meeting_id: row.id,
      user_id: row.user_id,
      recorded_at: row.recorded_at,
      source: row.source,
      meeting_type: row.meeting_type,
      labeled_text: row.transcription || '',
      duration_seconds: row.duration_seconds || 0,
    }
  }];
}

// agrupa segments contíguos do mesmo speaker em turnos
const turns = [];
for (const s of segments) {
  const last = turns[turns.length - 1];
  if (last && last.speaker === s.speaker) {
    last.text += s.text;
  } else {
    turns.push({ speaker: s.speaker, text: s.text });
  }
}

// monta texto rotulado: "Nome: texto" ou "Speaker X: texto" se não rotulado
const lines = turns.map(t => {
  const name = labels[t.speaker] || `Speaker ${t.speaker}`;
  return `${name}: ${t.text.trim()}`;
});

return [{
  json: {
    meeting_id: row.id,
    user_id: row.user_id,
    recorded_at: row.recorded_at,
    source: row.source,
    meeting_type: row.meeting_type,
    labeled_text: lines.join('\n'),
    duration_seconds: row.duration_seconds || 0,
  }
}];

// coleta as N saídas do GPT, parseia as actions de cada run, monta o prompt do juiz
const items = $input.all();
function parse(raw) {
  let p;
  if (raw.message && raw.message.content) p = typeof raw.message.content === 'string' ? JSON.parse(raw.message.content) : raw.message.content;
  else if (raw.content) p = typeof raw.content === 'string' ? JSON.parse(raw.content) : raw.content;
  else if (raw.text) p = typeof raw.text === 'string' ? JSON.parse(raw.text) : raw.text;
  else p = raw;
  return p || {};
}
const parsed = items.map(it => parse(it.json));
const runs = parsed.map(p => Array.isArray(p.actions) ? p.actions : []);
const __ctx = $('Build Distiller Input').first().json;
let summary = __ctx.summary || '', executive_summary = __ctx.executive_summary || null;
const lines = [];
runs.forEach((acts, ri) => {
  lines.push('EXECUÇÃO ' + (ri + 1) + ':');
  acts.forEach((a, ii) => lines.push('  [' + (ri + 1) + '.' + ii + '] ' + (a.titulo || '') + ' (owner=' + (a.owner || '') + ')'));
});
const judgePrompt =
  'Abaixo, tarefas extraídas da MESMA reunião em várias execuções do mesmo modelo. ' +
  'Diferenças de REDAÇÃO são esperadas — IGNORE. Agrupe os itens que são a MESMA tarefa subjacente ' +
  '(mesmo entregável/objetivo e mesmo dono). Itens distintos NÃO devem ser juntados só por tema parecido. ' +
  'Cada item pertence a exatamente um grupo. Para cada grupo dê "canonical" — uma FRASE DIRETA E COMPLETA no estilo do próprio título (verbo no infinitivo + o ENTREGÁVEL CONCRETO), escolhendo/unindo a redação MAIS COMPLETA entre os membros; NÃO encurte para rótulo genérico ' +
  'e "refs" (lista de "R.I" dos membros). Retorne JSON: {"grupos":[{"canonical":"...","refs":["1.0","2.3"]}]}\n\n' +
  lines.join('\n');
return [{ json: { judgePrompt: judgePrompt, runs: runs, summary: summary, executive_summary: executive_summary, raw_ai_response: JSON.stringify({ summary: summary, executive_summary: executive_summary }) } }];

// AGREGA por maioria (self-consistency N=3) + enforcement determinístico
function normOwner(o){const s=(o==null?'':String(o)).trim(); if(!s)return 'vitor'; if(/^vitor$/i.test(s))return 'vitor'; if(/^speaker\b/i.test(s))return '?'; return s;}
function coerceAcao(owner,acao){const o=normOwner(owner); if(o==='vitor')return 'executar'; return ['cobrar','aguardar'].includes(acao)?acao:'cobrar';}
function cleanPrazo(t){if(t==null)return null; const s=String(t).trim(); if(!s)return null; const re=/(hoje|amanh[ãa]|ontem|segunda|ter[çc]a|quarta|quinta|sexta|s[áa]bado|domingo|semana|mês|meses|que vem|daqui a|fim de semana|feriado|manh[ãa]|tarde|noite|madrugada|daily|janeiro|fevereiro|mar[çc]o|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro|\d{1,2}\s*\/\s*\d{1,2}|dia\s+\d{1,2}|\d{1,2}\s*h\b|\d{1,2}:\d{2})/i; return re.test(s)?s:null;}
function mode(vals){const c={}; let best=null,bn=0; for(const v of vals){ if(v==null||v==='')continue; const k=(typeof v==='object')?JSON.stringify(v):String(v); c[k]=(c[k]||0)+1; if(c[k]>bn){bn=c[k]; best=v;} } return best;}

const ctx = $('Build Judge Prompt').first().json;
const runs = ctx.runs || [];
const N = runs.length || 3;
const maj = Math.floor(N/2)+1;
const jr = $input.first().json;
let grupos=[];
try{ let p = (jr.message && jr.message.content) ? jr.message.content : (jr.content||jr.text||jr); p = (typeof p==='string')?JSON.parse(p):p; grupos = p.grupos||[]; }catch(e){ grupos=[]; }

const meetingId = $('3. Prepare Metadata').first().json.meeting_id;
const rawJson = ctx.raw_ai_response || '{}';
const summary = ctx.summary || '';

const out=[];
for(const g of grupos){
  const refs=[]; const runset=new Set();
  for(const ref of (g.refs||[])){
    const m=String(ref).split('.'); const ri=parseInt(m[0],10)-1, ii=parseInt(m[1],10);
    if(runs[ri] && runs[ri][ii]){ refs.push(runs[ri][ii]); runset.add(ri); }
  }
  if(!refs.length) continue;
  const cov=runset.size;
  let rep=refs[0]; for(const r of refs){ if(String(r.descricao||'').length>String(rep.descricao||'').length) rep=r; }
  const owner=normOwner(mode(refs.map(r=>r.owner)));
  const acao=coerceAcao(owner, mode(refs.map(r=>r.acao)));
  let pessoas=[]; for(const r of refs){ for(const pp of (r.pessoas_envolvidas||[])){ if(!pessoas.some(x=>String(x).trim().toLowerCase()===String(pp).trim().toLowerCase())) pessoas.push(pp);} }
  if(owner!=='vitor'&&owner!=='?'&&!pessoas.some(x=>String(x).trim().toLowerCase()===owner.toLowerCase())) pessoas.unshift(owner);
  pessoas=pessoas.filter(p=>!/^speaker\b/i.test(String(p).trim()));
  const prio=mode(refs.map(r=>r.prioridade));
  out.push({
    titulo: g.canonical || rep.titulo || '(sem título)',
    descricao: rep.descricao || '',
    owner: owner, acao: acao,
    prazo: mode(refs.map(r=>r.prazo_iso)) || null,
    prazo_text: cleanPrazo(mode(refs.map(r=>r.prazo_text))),
    prioridade: ['baixa','media','alta','urgente'].includes(prio)?prio:'media',
    evidencia: rep.evidencia || '',
    area_raw: mode(refs.map(r=>r.area)) || null,
    pessoas_raw: JSON.stringify(pessoas),
    precisa_revisao: cov < maj
  });
}
if(!out.length){
  return [{ json:{ meeting_id:meetingId, summary:summary, raw_ai_response:rawJson, no_actions:true } }];
}
return out.map((a,i)=>({ json: Object.assign({ meeting_id:meetingId, summary:summary, raw_ai_response:rawJson, idx:i, total:out.length }, a) }));

// Junta o relatório do Stage A + texto rotulado + (feedback) pro distiller.
function parse(raw){ let p; if(raw.message&&raw.message.content) p= typeof raw.message.content==='string'?JSON.parse(raw.message.content):raw.message.content; else if(raw.content) p=typeof raw.content==='string'?JSON.parse(raw.content):raw.content; else p=raw; return p||{}; }
const sa = parse($input.first().json);
const blt = $('Build Labeled Text').first().json;
const fb = { block: '' };
return [{ json: {
  summary: sa.summary || '',
  executive_summary: sa.executive_summary || '',
  labeled_text: blt.labeled_text || '',
  feedback_block: (fb && fb.block) || '',
} }];
